footer.pie{margin:24px 0 0;padding-bottom:84px}footer.pie .medios{display:flex;flex-wrap:wrap;gap:6px}footer.pie .medios span{border:1px solid rgba(255,255,255,.14);border-radius:6px;padding:3px 8px;font-size:12px;font-weight:700}</style>
</head>
<body>
<?= gtm_body_html() . anuncio_html() ?>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,600;12..96,700;12..96,800&family=Manrope:wght@400;500;600;700;800&family=JetBrains+Mono:wght@500&display=swap">
<style>
/* Layout: tienda de un solo carril para el celular — cámara del filtro como protagonista, resultados en tarjetas, pedido en 3 pasos en hoja inferior, menú al pulgar */
:root{
  --bg:#f1f5ff; --panel:#ffffff; --ink:#0b1a45; --muted:#566287; --line:#d9e2fa;
  --accent:#1a5cff; --accent-ink:#ffffff; --accent-soft:#e3ecff; --deep:#0b1f6b; --deep-2:#1236a8; --glow:#38d6ff;
  --ok:#2e7d4f; --ok-soft:#dff1e6; --warn:#a86400; --warn-soft:#fbefd9; --bad:#b3261e; --bad-soft:#f9e1df; --wa:#1fa855;
  --f-display:"Bricolage Grotesque","Avenir Next",system-ui,sans-serif;
  --f-body:"Manrope",system-ui,-apple-system,"Segoe UI",sans-serif;
  --f-mono:"JetBrains Mono",ui-monospace,Menlo,monospace;
  --r:16px; --shadow:0 1px 2px rgba(11,26,69,.06),0 8px 24px rgba(11,26,69,.07);
}
@media (prefers-color-scheme: dark){:root:not([data-theme="light"]){
  --bg:#081230; --panel:#101d4a; --ink:#e6ecff; --muted:#9fb0e6; --line:#22336b;
  --accent:#5b8cff; --accent-ink:#04103a; --accent-soft:#16296b; --deep:#0b1f6b; --deep-2:#1236a8; --glow:#38d6ff;
  --ok:#6cc790; --ok-soft:#16301f; --warn:#f0a73a; --warn-soft:#33270f; --bad:#f2857b; --bad-soft:#3a1c1a; --wa:#25b862;
  --shadow:0 1px 2px rgba(0,0,0,.3),0 8px 24px rgba(0,0,0,.25);
  color-scheme:dark}}
:root[data-theme="dark"]{
  --bg:#081230; --panel:#101d4a; --ink:#e6ecff; --muted:#9fb0e6; --line:#22336b;
  --accent:#5b8cff; --accent-ink:#04103a; --accent-soft:#16296b; --deep:#0b1f6b; --deep-2:#1236a8; --glow:#38d6ff;
  --ok:#6cc790; --ok-soft:#16301f; --warn:#f0a73a; --warn-soft:#33270f; --bad:#f2857b; --bad-soft:#3a1c1a; --wa:#25b862;
  --shadow:0 1px 2px rgba(0,0,0,.3),0 8px 24px rgba(0,0,0,.25);
  color-scheme:dark}
*{box-sizing:border-box}
[hidden]{display:none!important}
body{background:var(--bg);color:var(--ink);font-family:var(--f-body);font-size:15px;line-height:1.5;margin:0;-webkit-tap-highlight-color:transparent}
button,input,select,textarea{font:inherit;color:inherit}
:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.wrap{max-width:780px;margin:0 auto;padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px))}
main.wrap{padding-block:0 calc(100px + env(safe-area-inset-bottom,0px));display:flex;flex-direction:column;gap:20px}
@media (prefers-reduced-motion:no-preference){.rise{animation:rise .35s ease-out both}@keyframes rise{from{transform:translateY(8px);opacity:.4}to{transform:none;opacity:1}}}

/* ---------- Encabezado ---------- */
.hero{background:radial-gradient(120% 90% at 100% 0%,var(--deep-2) 0%,var(--deep) 55%);color:#e9f6f3;padding-block:16px 30px;position:relative;overflow:hidden}
.hero::before{content:"";position:absolute;right:-70px;top:-50px;width:240px;height:240px;border-radius:50%;border:30px solid rgba(56,214,255,.12)}
.hero .wrap{display:flex;flex-direction:column;gap:14px;position:relative;z-index:1}
.top{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap}
.logo{font-family:var(--f-display);font-weight:800;font-size:24px;letter-spacing:-.01em;display:flex;align-items:center;gap:8px}
.logo svg{width:34px;height:34px}.logo .lg-t{display:flex;flex-direction:column;line-height:1.02;font-size:20px}.logo .lg-t small{font-size:9.5px;letter-spacing:.3em;text-transform:uppercase;color:rgba(255,255,255,.72);font-weight:700;margin-top:2px}
.logo b{color:var(--glow);font-weight:inherit}
.city{display:flex;align-items:center;gap:6px;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.18);border-radius:999px;padding:4px 6px 4px 12px;font-size:13px}
.city select{background:transparent;border:0;color:#fff;font-weight:700;padding:2px 4px;max-width:150px}
.city select option{color:#111}
.hero h1{font-family:var(--f-display);font-weight:700;font-size:clamp(27px,7vw,40px);line-height:1.05;margin:0;text-wrap:balance;letter-spacing:-.015em}
.hero p.lead{margin:0;color:#b9d8d2;max-width:52ch}

/* Cámara del filtro: protagonista */
.cam{position:relative;display:grid;grid-template-columns:auto 1fr;gap:16px;align-items:center;background:linear-gradient(135deg,rgba(56,214,255,.22),rgba(56,214,255,.06));border:1.5px solid rgba(56,214,255,.55);border-radius:20px;padding:18px;cursor:pointer;transition:transform .15s}
.cam:active{transform:scale(.99)}
.cam .lens{width:76px;height:76px;border-radius:22px;background:var(--glow);display:grid;place-items:center;box-shadow:0 0 0 6px rgba(56,214,255,.18)}
.cam .lens svg{width:40px;height:40px;stroke:#0b1f6b;fill:none;stroke-width:1.8}
.cam b{display:block;font-family:var(--f-display);font-size:23px;line-height:1.1;color:#fff}
.cam span{color:#c4e4de;font-size:14px;line-height:1.35}
.cam input{position:absolute;inset:0;opacity:0;cursor:pointer;width:100%}
.alt{display:flex;gap:8px;flex-wrap:wrap}
.alt label{position:relative;display:inline-flex;align-items:center;gap:8px;border:1px solid rgba(255,255,255,.25);border-radius:999px;padding:7px 12px;font-size:13.5px;cursor:pointer;color:#e1f2ee}
.alt label svg{width:18px;height:18px;stroke:var(--glow);fill:none;stroke-width:1.8}
.alt input[type=file]{position:absolute;inset:0;opacity:0;cursor:pointer;width:100%}
.searchbox{display:flex;gap:8px;background:var(--panel);border-radius:14px;padding:6px;box-shadow:0 10px 30px rgba(0,0,0,.18)}
.searchbox input{flex:1 1 auto;min-width:0;border:0;background:transparent;padding:10px;font-size:16px;color:var(--ink)}
.searchbox input:focus{outline:none}
.searchbox button{border:0;background:var(--accent);color:var(--accent-ink);border-radius:10px;padding:0 16px;font-weight:800;cursor:pointer}
.chips{display:flex;gap:6px;flex-wrap:wrap}
.chips button{border:1px solid rgba(255,255,255,.22);background:transparent;color:#d4ece7;border-radius:999px;padding:4px 10px;font-family:var(--f-mono);font-size:12px;cursor:pointer}

/* Franja de confianza */
.trust{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-top:14px;position:relative;z-index:1}
.trust div{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:11px 10px;font-size:12.5px;color:var(--muted);line-height:1.3;box-shadow:var(--shadow)}
.trust svg{width:20px;height:20px;stroke:var(--accent);fill:none;stroke-width:1.9;display:block;margin-bottom:4px}
.trust b{display:block;color:var(--ink);font-size:13.5px}

h2{font-family:var(--f-display);font-weight:700;font-size:22px;margin:0;letter-spacing:-.01em;text-wrap:balance}
.sub{color:var(--muted);margin:0;font-size:14px}
.note{font-size:13.5px;border-radius:12px;padding:10px 12px;background:var(--warn-soft);border-left:3px solid var(--warn)}
.note.info{background:var(--accent-soft);border-left-color:var(--accent)}
.example{display:inline-block;font-size:10.5px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;background:var(--warn-soft);color:var(--warn);padding:2px 7px;border-radius:4px}

/* Lectura de la foto */
.scan{background:var(--panel);border:1px solid var(--line);border-radius:var(--r);padding:14px;display:grid;grid-template-columns:110px 1fr;gap:14px;align-items:center;box-shadow:var(--shadow)}
.scan .ph{position:relative;width:110px;height:140px;border-radius:12px;overflow:hidden;background:var(--bg)}
.scan .ph img{width:100%;height:100%;object-fit:cover}
.scan .ph::after{content:"";position:absolute;left:0;right:0;height:3px;background:var(--glow);box-shadow:0 0 12px var(--glow);top:0;opacity:0}
.scan.busy .ph::after{opacity:1}
@media (prefers-reduced-motion:no-preference){.scan.busy .ph::after{animation:scanline 1.4s ease-in-out infinite alternate}@keyframes scanline{from{top:4%}to{top:94%}}}
.vs{display:grid;grid-template-columns:1fr auto 1fr;gap:10px;align-items:center;text-align:center;font-size:12px;color:var(--muted)}
.vs .box{background:var(--bg);border-radius:12px;padding:8px;display:grid;place-items:center;height:120px;overflow:hidden}
.vs .box img{max-height:104px;object-fit:contain}
.vs .box svg{width:54px;height:80px}
.vs .eq{font-family:var(--f-display);font-size:22px;color:var(--ok)}

/* Buscador: voz y sugerencias */
.searchbox .mic{width:44px;flex:0 0 auto;border:0;border-radius:10px;background:var(--accent-soft);display:grid;place-items:center;cursor:pointer;padding:0}
.searchbox .mic svg{width:22px;height:22px;fill:none;stroke:var(--accent);stroke-width:2}
.searchbox .mic.on{background:var(--bad)}
.searchbox .mic.on svg{stroke:#fff}
@media (prefers-reduced-motion:no-preference){.searchbox .mic.on{animation:pulse 1s ease-in-out infinite}@keyframes pulse{50%{box-shadow:0 0 0 7px rgba(242,133,123,.25)}}}
.sugg{background:var(--panel);border-radius:14px;box-shadow:0 10px 30px rgba(0,0,0,.25);overflow:hidden;margin-top:-6px;color:var(--ink)}
.sugg button{display:grid;grid-template-columns:44px minmax(0,1fr) auto;gap:10px;align-items:center;width:100%;border:0;border-top:1px solid var(--line);background:transparent;padding:8px 10px;text-align:left;cursor:pointer}
.sugg button:first-child{border-top:0}
.sugg button[aria-selected="true"],.sugg button:hover{background:var(--accent-soft)}
.sugg .th{width:44px;height:52px;border-radius:8px;background:#fff;display:grid;place-items:center;overflow:hidden}
.sugg .th img{width:100%;height:100%;object-fit:contain}
.sugg .th svg{width:24px;height:40px}
.sugg b{display:block;font-size:14px;line-height:1.2}
.sugg small{font-family:var(--f-mono);color:var(--accent);font-size:12px}
.sugg .pr{font-weight:800;font-size:13.5px;font-variant-numeric:tabular-nums}
.sugg .more{display:block;text-align:center;font-weight:700;color:var(--accent);font-size:13.5px;grid-template-columns:none}

/* Catálogo por marca */
.cat-title{margin:0 0 -12px}
.brandbar{position:sticky;top:0;z-index:6;background:var(--bg);margin-inline:-16px;padding:8px 16px;display:flex;flex-direction:column;gap:8px;border-bottom:1px solid var(--line)}
.brands{display:flex;gap:8px;overflow-x:auto;scrollbar-width:none;margin-inline:-16px;padding-inline:16px}
.brands::-webkit-scrollbar{display:none}
.brands button{flex:0 0 auto;display:flex;align-items:center;gap:7px;border:1.5px solid var(--line);background:var(--panel);border-radius:999px;padding:7px 13px;font-weight:800;font-size:14px;cursor:pointer;color:var(--ink)}
.brands button i{width:9px;height:9px;border-radius:50%;background:var(--c,var(--accent));flex:0 0 auto}
.brands button small{font-weight:700;color:var(--muted);font-size:12px}
.brands button[aria-selected="true"]{border-color:var(--accent);background:var(--accent);color:var(--accent-ink)}
.brands button[aria-selected="true"] small{color:var(--accent-ink)}
.segs{display:flex;gap:4px;background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:3px}
.segs button{flex:1;border:0;background:transparent;border-radius:9px;padding:7px 4px;font-weight:700;font-size:13px;color:var(--muted);cursor:pointer}
.segs button[aria-pressed="true"]{background:var(--accent-soft);color:var(--ink)}
.cat-meta{display:flex;flex-direction:column;gap:8px;margin-top:-8px}
.cat-meta:has(#list-sub[hidden]):has(#citybox:empty){display:none}
.ghead{grid-column:1/-1;display:flex;align-items:baseline;gap:8px;margin-top:6px}
.ghead:first-child{margin-top:0}
.ghead b{font-family:var(--f-display);font-size:17px}
.ghead span{font-size:12.5px;color:var(--muted)}

/* Tarjetas de producto */
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(158px,1fr));gap:10px}
.card{background:var(--panel);border:1px solid var(--line);border-radius:var(--r);padding:10px;display:flex;flex-direction:column;gap:8px;min-width:0;box-shadow:var(--shadow)}
.card .cinfo{display:flex;flex-direction:column;gap:3px;min-width:0;flex:1}
.card .price{font-size:21px}
.card .head{display:flex;gap:12px;align-items:flex-start}
.pbig{position:relative;height:180px;width:100%;border-radius:12px;background:#fff;border:1px solid var(--line);display:grid;place-items:center;overflow:hidden;padding:8px;cursor:zoom-in}
.pbig img{height:162px;width:100%;object-fit:contain;display:block}
.pbig svg{height:130px;width:auto}
.lupa{position:absolute;right:7px;bottom:7px;display:flex;align-items:center;gap:5px;background:rgba(11,31,107,.82);color:#fff;border-radius:999px;padding:6px;font-size:12.5px;font-weight:800;backdrop-filter:blur(4px)}
.lupa svg{width:18px;height:18px;fill:none;stroke:#fff;stroke-width:2.2;display:block}
.photo{position:relative;height:min(42vh,330px);width:100%;border-radius:16px;background:#fff;border:1px solid var(--line);display:grid;place-items:center;overflow:hidden;padding:12px;cursor:zoom-in}
.photo>img,.photo>svg{position:absolute;inset:12px;width:calc(100% - 24px);height:calc(100% - 24px);object-fit:contain}
.photo.sm{height:min(30vh,220px)}
.photo .lupa{padding:7px 12px}
.pimg{width:92px;height:124px;flex:0 0 auto;border-radius:12px;background:#fff;border:1px solid var(--line);display:grid;place-items:center;overflow:hidden;padding:4px}
.pimg img{width:100%;height:100%;object-fit:contain;image-rendering:auto}
.pimg svg{width:50px;height:76px}
.card .brand{font-size:11.5px;font-weight:800;letter-spacing:.07em;text-transform:uppercase;color:var(--muted)}
.card h3{margin:0;font-size:15px;line-height:1.2}
.card .ref{font-size:12px}
.ref{font-family:var(--f-mono);font-size:13px;color:var(--accent);word-break:break-all}
.badges{display:flex;gap:6px;flex-wrap:wrap}
.badge{font-size:11.5px;font-weight:800;padding:3px 8px;border-radius:999px;background:var(--accent-soft);color:var(--ink)}
.badge.ok{background:var(--ok-soft);color:var(--ok)} .badge.warn{background:var(--warn-soft);color:var(--warn)} .badge.bad{background:var(--bad-soft);color:var(--bad)}
.price{font-family:var(--f-display);font-weight:700;font-size:25px;font-variant-numeric:tabular-nums;line-height:1}
.eta{font-size:13px;color:var(--muted);display:flex;gap:6px;align-items:flex-start;margin-top:4px}
.eta svg{width:16px;height:16px;flex:0 0 auto;stroke:var(--accent);fill:none;stroke-width:2;margin-top:2px}
.fits{font-size:12.5px;color:var(--muted)}
.card .actions{display:flex;gap:6px;align-items:center}
.card .actions .btn{padding:10px 8px}
.card .icon-btn{width:42px;height:42px}
.icon-btn{width:44px;height:44px;border-radius:12px;border:1px solid var(--line);background:var(--bg);display:grid;place-items:center;cursor:pointer;color:var(--muted);text-decoration:none;flex:0 0 auto}
.icon-btn svg{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:1.8}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;border:1px solid var(--accent);background:var(--accent);color:var(--accent-ink);border-radius:12px;padding:12px 16px;font-weight:800;cursor:pointer;text-decoration:none;transition:transform .1s}
.btn:active{transform:scale(.98)}
.btn.ghost{background:transparent;color:var(--accent)}
.btn.wa{background:var(--wa);border-color:var(--wa);color:#fff}
.btn.block{width:100%}
.btn:disabled{opacity:.5;cursor:not-allowed}
.btn svg:not([width]){width:20px;height:20px;flex:0 0 auto;fill:none;stroke:currentColor;stroke-width:2.2;stroke-linejoin:round}
.row{display:flex;flex-wrap:wrap;gap:8px;align-items:center}

/* Comprobador */
.check{background:var(--panel);border:1px solid var(--line);border-radius:var(--r);padding:14px;display:flex;flex-direction:column;gap:10px;box-shadow:var(--shadow)}
.check form{display:flex;gap:8px}
.check input{flex:1 1 auto;min-width:0;background:var(--bg);border:1px solid var(--line);border-radius:10px;padding:10px 12px;font-size:16px;color:var(--ink)}
.verdict{display:flex;gap:10px;align-items:flex-start;border-radius:12px;padding:10px 12px;font-size:14px}
.verdict.yes{background:var(--ok-soft)} .verdict.no{background:var(--warn-soft)}
.verdict svg{width:22px;height:22px;flex:0 0 auto;fill:none;stroke-width:2.2}
.verdict.yes svg{stroke:var(--ok)} .verdict.no svg{stroke:var(--warn)}
.verdict a{color:var(--accent);font-weight:700}

/* Medidor de vida del filtro */
.sl-grid{display:grid;grid-template-columns:132px minmax(0,1fr);gap:14px;align-items:center}
@media (max-width:360px){.sl-grid{grid-template-columns:1fr}.gauge{margin:0 auto}}
.sl-in{display:flex;flex-direction:column;gap:10px;min-width:0}
.sl-in .f{display:flex;flex-direction:column;gap:4px;font-size:14px}
.sl-in input[type=month]{background:var(--bg);border:1px solid var(--line);border-radius:10px;padding:9px 10px;font-size:16px;color:var(--ink);min-width:0;width:100%}
.sintomas{display:flex;flex-wrap:wrap;gap:6px;margin-top:6px}
.sintomas button{border:1.5px solid var(--line);background:var(--bg);border-radius:999px;padding:6px 11px;font-size:13px;font-weight:700;cursor:pointer;color:var(--ink)}
.sintomas button[aria-pressed="true"]{border-color:var(--bad);background:var(--bad-soft);color:var(--bad)}
.gauge{width:132px;height:132px;position:relative}
.gauge svg{width:100%;height:100%;transform:rotate(-90deg)}
.gauge .trk{fill:none;stroke:var(--line);stroke-width:11}
.gauge .val{fill:none;stroke-width:11;stroke-linecap:round;transition:stroke-dashoffset .8s cubic-bezier(.2,.8,.2,1),stroke .4s}
.gauge .lbl{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;line-height:1.1}
.gauge .lbl b{font-family:var(--f-display);font-size:28px;font-variant-numeric:tabular-nums}
.gauge .lbl span{font-size:11.5px;color:var(--muted);max-width:90px}
.gauge.sm{width:64px;height:64px}
.gauge.sm .trk,.gauge.sm .val{stroke-width:12}
.gauge.sm .lbl b{font-size:15px}
.gauge.sm .lbl span{display:none}
.sl-verdict{border-radius:12px;padding:10px 12px;font-size:14px;display:flex;flex-direction:column;gap:8px}
.sl-verdict.ok{background:var(--ok-soft)} .sl-verdict.warn{background:var(--warn-soft)} .sl-verdict.bad{background:var(--bad-soft)}
.ord{display:grid;grid-template-columns:64px minmax(0,1fr);gap:12px;padding:12px 14px;border-top:1px solid var(--line);align-items:center}
.ord:first-child{border-top:0}
.ord .acts{grid-column:1/-1;display:flex;gap:8px}
.ord .acts .btn{flex:1;padding:9px 10px;font-size:14px}

/* Preguntas */
details.faq{background:var(--panel);border:1px solid var(--line);border-radius:14px}
details.faq summary{cursor:pointer;padding:13px 14px;font-weight:700;list-style:none;display:flex;justify-content:space-between;gap:10px}
details.faq summary::after{content:"+";color:var(--accent);font-family:var(--f-mono)}
details.faq[open] summary::after{content:"−"}
details.faq p{margin:0;padding:0 14px 14px;color:var(--muted);font-size:14px}
.faqs{display:flex;flex-direction:column;gap:8px}

/* ---------- Visor de foto con lupa ---------- */
.zoom{position:fixed;inset:0;z-index:50;background:#071618;display:flex;flex-direction:column;color:#e9f6f3}
.zbar{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:calc(8px + env(safe-area-inset-top,0px)) 12px 8px 16px}
.zhint{font-size:12.5px;color:#a9c9c3}
.zx{width:44px;height:44px;border-radius:50%;border:0;background:rgba(255,255,255,.12);color:#fff;font-size:20px;cursor:pointer;flex:0 0 auto}
.zstage{flex:1;min-height:0;position:relative;overflow:hidden;background:#fff;touch-action:none;cursor:grab;display:grid;place-items:center}
.zstage:active{cursor:grabbing}
.zstage img{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;transform-origin:center;user-select:none;-webkit-user-drag:none;will-change:transform}
