function cartSVG(p) {
  const c = p.color, cap = "#d8e2e1";
  const body = {
    cin: `<rect x="14" y="10" width="26" height="62" rx="6" fill="${c}"/><rect x="18" y="4" width="18" height="10" rx="3" fill="${cap}"/><rect x="14" y="28" width="26" height="5" fill="#ffffff55"/>`,
    qin: `<rect x="12" y="14" width="30" height="58" rx="8" fill="${c}"/><rect x="20" y="4" width="14" height="12" rx="3" fill="${cap}"/><circle cx="27" cy="40" r="7" fill="#ffffff55"/>`,
    cu1: `<rect x="15" y="12" width="24" height="60" rx="4" fill="${c}"/><rect x="21" y="3" width="12" height="11" rx="2" fill="${cap}"/><rect x="15" y="20" width="24" height="3" fill="#ffffff55"/><rect x="15" y="60" width="24" height="3" fill="#ffffff55"/>`,
    lt: `<rect x="17" y="8" width="20" height="66" rx="10" fill="${c}"/><rect x="23" y="2" width="8" height="9" rx="2" fill="${cap}"/><rect x="17" y="22" width="20" height="4" fill="#ffffff55"/>`,
    twist: `<rect x="14" y="16" width="26" height="56" rx="5" fill="${c}"/><path d="M18 16 L22 6 H32 L36 16Z" fill="${cap}"/><rect x="14" y="30" width="26" height="4" fill="#ffffff55"/>`,
    push: `<rect x="13" y="8" width="28" height="64" rx="7" fill="${c}"/><rect x="13" y="8" width="28" height="12" rx="7" fill="${cap}"/><circle cx="27" cy="46" r="6" fill="#ffffff55"/>`
  }[p.forma] || "";
  return `<svg viewBox="0 0 54 80" aria-hidden="true">${body}</svg>`;
}
