function bogotaNow() {
  const parts = new Intl.DateTimeFormat("en-CA", { timeZone: "America/Bogota", year: "numeric", month: "2-digit", day: "2-digit" }).formatToParts(new Date());
  const g = t => +parts.find(p => p.type === t)?.value;
  return { y: g("year"), m: g("month"), d: g("day") };
}
function addBusinessDays(n) {   // lunes a viernes
  const b = bogotaNow(), d = new Date(Date.UTC(b.y, b.m - 1, b.d, 12));
  let k = 0;
  while (k < n) { d.setUTCDate(d.getUTCDate() + 1); const w = d.getUTCDay(); if (w !== 0 && w !== 6) k++; }
  return d;
}
// Precio del pack de 2: el fijado en el catálogo, o 2 unidades con el descuento general
const packPrecio = p => p.pack || Math.round(p.precio * 2 * (1 - NEGOCIO.descuentoPack) / 100) * 100;
const packAhorro = p => Math.round((1 - packPrecio(p) / (p.precio * 2)) * 100);
