    const envio = city === "Cali" ? NEGOCIO.domicilioCali : NEGOCIO.domicilioArea;
    return { local: true, instala: INSTALA_EN.includes(city), envio,
      corto: sinStock ? `Por encargo: ${NEGOCIO.diasEncargo} días hábiles` : costoInst(p) ? `Domicilio gratis · instalación ${COP(costoInst(p))}` : "Domicilio e instalación gratis",
      largo: sinStock ? `Lo pedimos al proveedor y llega en unos ${NEGOCIO.diasEncargo} días hábiles. Te avisamos por correo.` : "Te llamamos para acordar el día y la hora." };
  }
  const n = sinStock ? Math.max(NEGOCIO.diasEncargo, diasCiudad(city)) : diasCiudad(city);
  return { local: false, instala: false, envio: PRINCIPALES.includes(city) ? NEGOCIO.envioPrincipal : NEGOCIO.envioOtros,
    corto: `Envío gratis · llega el ${fmtCorto(addBusinessDays(n))}`, largo: `Envío gratis. Llega en ${n} días hábiles por transportadora (hacia el ${fmtDay(addBusinessDays(n))}). Te mandamos el número de guía.` };
}
const city = () => $("#city").value;

/* ===================== BÚSQUEDA ===================== */
const norm = s => String(s || "").toUpperCase().normalize("NFD").replace(/[̀-ͯ]/g, "").replace(/[^A-Z0-9]/g, "");
function buscar(q) {
  const n = norm(q); if (n.length < 3) return [];
  const hits = [];
  for (const p of CATALOGO) {
    let s = 0, por = "";
    for (const r of p.refs) { const rn = norm(r); if (rn === n) { s = Math.max(s, 100); por = "referencia " + r; } else if (n.length >= 4 && (rn.includes(n) || (n.includes(rn) && rn.length >= 4))) { if (s < 70) { s = 70; por = "referencia " + r; } } }
    for (const m of p.modelos) { const mn = norm(m); if (mn === n || (n.length >= 6 && (mn.startsWith(n) || n.startsWith(mn)))) { if (s < 90) { s = 90; por = "nevecón " + m; } } }
    if (!s && n.length >= 4 && norm(p.marca + p.nombre).includes(n)) { s = 30; por = "nombre"; }
    if (s) hits.push({ p, s, por });
  }
  return hits.sort((a, b) => b.s - a.s || (a.p.tipo === "estandar" ? -1 : 1));
}
function stockBadge(p) {
  if (!p.stock) return '<span class="badge warn">Por encargo</span>';
  if (p.stock <= 3) return `<span class="badge warn">Últimas ${p.stock} unidades</span>`;
  return '<span class="badge ok">Disponible</span>';
}
const ubic = p => /-ex-/.test(p.id) ? "externo" : "interno";
const costoInst = p => p && ubic(p) === "externo" ? NEGOCIO.instalacionExterno : NEGOCIO.instalacion;
const UBIC = { interno: "Interno", externo: "Externo" };
const corto = p => p.nombre.replace(/^Filtro /, "");
const fotoHTML = (p, lazy) => IMGS[p.id] ? `<img src="${IMGS[p.id]}" alt="${esc(p.nombre)}"${lazy ? ' loading="lazy"' : ""}>` : cartSVG(p);
const shareTxt = p => `Mira este filtro para nevecón: ${p.nombre} (${p.ref}) a ${COP(p.precio)} en ${NEGOCIO.nombre}.`;
function cardHTML(p, por) {
  const d = delivery(city(), p);
  return `<article class="card rise">
    <button class="pbig" type="button" data-zoom="${p.id}" aria-label="Ver grande la foto de ${esc(p.nombre)}">${fotoHTML(p, true)}<span class="lupa">${ICON.zoom}</span></button>
    <div class="cinfo"><span class="brand">${esc(p.marca)} · ${UBIC[ubic(p)]}</span><h3>${esc(corto(p))}</h3><span class="ref">${esc(p.ref)}</span>
      ${p.stock > 3 ? "" : `<div class="badges">${stockBadge(p)}</div>`}</div>
    ${por ? `<div class="fits">Coincide por ${esc(por)}</div>` : ""}
    <div><div class="price">${COP(p.precio)}</div><div class="eta">${ICON.truck}${city() ? `<span>${esc(d.corto)}</span>` : `<button class="linkbtn" type="button" data-pickcity>¿Cuándo te llega? Elige tu ciudad</button>`}</div></div>
    <div class="actions"><button class="btn" type="button" data-buy="${p.id}" style="flex:1">Pedir</button><a class="icon-btn" href="https://wa.me/?text=${encodeURIComponent(shareTxt(p))}" data-share="${p.id}" target="_blank" rel="noopener" aria-label="Compartir">${ICON.share}</a></div>
  </article>`;
}
