/* Sugerencias mientras escribe: por referencia, modelo o marca */
function sugerencias(q) {
  const n = norm(q); if (n.length < 2) return [];
  const marca = MARCAS.find(([m]) => norm(m).startsWith(n) || (n.length >= 3 && "EVERYDROP".startsWith(n) && m === "Whirlpool") || (n.length >= 3 && "GENERALELECTRIC".startsWith(n) && m === "GE"));
  if (marca) return CATALOGO.filter(p => p.marca === marca[0]);
  const hits = buscar(q).map(h => h.p);
  if (n.length === 2) CATALOGO.forEach(p => { if (!hits.includes(p) && p.refs.some(r => norm(r).startsWith(n))) hits.push(p); });
  return hits;
}
let suggSel = -1;
function renderSugg(q) {
  const list = sugerencias(q), box = $("#sugg"); suggSel = -1;
  if (!list.length) return hideSugg();
  box.innerHTML = list.slice(0, 5).map((p, i) => `<button type="button" role="option" id="sg-${i}" data-sg="${p.id}" aria-selected="false"><span class="th">${fotoHTML(p)}</span><span style="min-width:0"><b>${esc(corto(p))}</b><small>${esc(p.ref)}</small></span><span class="pr">${COP(p.precio)}</span></button>`).join("")
    + (list.length > 5 ? `<button type="button" class="more" data-sgall>Ver los ${list.length} resultados</button>` : "");
  box.hidden = false;
}
function hideSugg() { $("#sugg").hidden = true; $("#sugg").innerHTML = ""; suggSel = -1; }
