$("#q").addEventListener("keydown", e => {
  const items = [...$("#sugg").querySelectorAll("button")]; if ($("#sugg").hidden || !items.length) return;
  if (e.key === "ArrowDown" || e.key === "ArrowUp") {
    e.preventDefault(); suggSel = (suggSel + (e.key === "ArrowDown" ? 1 : -1) + items.length) % items.length;
    items.forEach((b, i) => b.setAttribute("aria-selected", String(i === suggSel))); $("#q").setAttribute("aria-activedescendant", items[suggSel].id || "");
  } else if (e.key === "Enter" && suggSel >= 0) { e.preventDefault(); items[suggSel].click(); }
  else if (e.key === "Escape") hideSugg();
});
