/* Buscar hablando: dice la referencia o el problema; si no está en el catálogo, le pregunta al asistente */
(() => {
  const SR = window.SpeechRecognition || window.webkitSpeechRecognition; if (!SR) return;
  const mic = $("#mic"); mic.hidden = false;
  let rec = null;
  mic.addEventListener("click", () => {
    if (rec) { rec.stop(); return; }
    try { rec = new SR(); } catch { mic.hidden = true; return; }
    rec.lang = "es-CO"; rec.interimResults = true; rec.maxAlternatives = 1;
    mic.classList.add("on"); $("#q").placeholder = "Te escucho… di la referencia";
    rec.onresult = ev => { const t = [...ev.results].map(r => r[0].transcript).join(" "); $("#q").value = t; renderSugg(t); };
    rec.onerror = () => {};
    rec.onend = () => {
      rec = null; mic.classList.remove("on"); $("#q").placeholder = "O escribe: DA29-00020B, LT700P…";
      const q = $("#q").value.trim(); if (!q) return;
      hideSugg();
      // "ele te mil pe" → "LT1000P": quita espacios para comparar con las referencias
      const junto = q.replace(/\s+/g, "");
      if (buscar(junto).length) { $("#q").value = junto; doSearch(junto); }
      else if (buscar(q).length) doSearch(q);
      else if (sample) { openChat(); askChat(q); }
      else doSearch(q);
    };
    try { rec.start(); } catch { rec = null; mic.classList.remove("on"); }
  });
})();
