    (leido ? buscar(leido) : []).forEach(h => ids.add(h.p.id));
    const list = CATALOGO.filter(p => ids.has(p.id)).sort((a, b) => (a.tipo === "estandar" ? -1 : 1));
    const leyenda = [d.marca, d.referencia_leida && "Filtro " + d.referencia_leida, d.modelo_leido && "Nevecón " + d.modelo_leido].filter(Boolean).join(" · ") || "sin referencia legible";
    box.innerHTML = list.length
      ? `<div class="check rise"><b style="font-size:17px">¡Lo encontramos!</b>
          <div class="vs"><div><div class="box"><img src="${url}" alt="Tu foto"></div>Tu foto</div><div class="eq">=</div><div><div class="box">${IMGS[list[0].id] ? `<img src="${IMGS[list[0].id]}" alt="">` : cartSVG(list[0])}</div>${esc(list[0].ref)}</div></div>
          <div class="sub">Leímos: <span class="ref">${esc(leyenda)}</span>${d.nota ? ". " + esc(d.nota) : ""}</div></div>`
      : `<div class="scan"><div class="ph"><img src="${url}" alt="Tu foto"></div><div><b>Leímos: <span class="ref">${esc(leyenda)}</span></b><div class="sub">No lo tenemos en el catálogo. Escríbenos y te lo conseguimos.</div><a class="btn wa" style="margin-top:8px" href="${waLink(`Hola, busco el filtro para: ${leido || "mi nevecón"}. ¿Lo tienen?`)}" target="_blank" rel="noopener">Escríbenos</a></div></div>`;
    if (list.length) renderGrid(list.map(p => ({ p, por: d.referencia_leida ? "referencia " + d.referencia_leida : d.modelo_leido ? "nevecón " + d.modelo_leido : "" })), "Este es tu filtro", "Toca la lupa para comparar la foto con la tuya.");
    if (leido) $("#q").value = leido;
  } catch (e) {
    box.innerHTML = `<div class="scan"><div class="ph"><img src="${url}" alt="Tu foto"></div><div><b>${e?.code === "not_granted" ? "No se dio permiso para leer la foto." : "No pudimos leer la foto."}</b><div class="sub">Escribe la referencia o mándanos la foto por WhatsApp.</div></div></div>`;
  }
}
