/* ===================== PEDIDO EN 3 PASOS ===================== */
// Celular colombiano → "57" + 10 dígitos empezando por 3; null si no es válido
function celularCO(s) {
  let d = String(s || "").replace(/\D/g, "");
  if (d.length === 12 && d.startsWith("57")) d = d.slice(2);
  return /^3\d{9}$/.test(d) ? "57" + d : null;
}
const waTo = (num, txt) => `https://wa.me/${num}?text=${encodeURIComponent(txt)}`;
