$("#grid").addEventListener("click", e => { const b = e.target.closest("[data-buy]"); if (b) startOrder(b.dataset.buy); });

/* ===================== VISOR CON LUPA ===================== */
const Z = { s: 1, x: 0, y: 0, pts: new Map(), base: null, tap: 0, tx: 0, ty: 0, id: null };
const zimg = $("#zimg"), zstage = $("#zstage");
function zApply(anim) {
  zimg.classList.toggle("anim", !!anim);
  zimg.style.transform = `translate(${Z.x}px, ${Z.y}px) scale(${Z.s})`;
  $("#z-pct").textContent = Math.round(Z.s * 100) + " %";
}
function zClamp() {
  if (Z.s <= 1.001) { Z.s = 1; Z.x = 0; Z.y = 0; return; }
  const r = zstage.getBoundingClientRect(), w = zimg.offsetWidth * Z.s, hh = zimg.offsetHeight * Z.s;
  const mx = Math.max(0, (w - r.width) / 2), my = Math.max(0, (hh - r.height) / 2);
  Z.x = Math.max(-mx, Math.min(mx, Z.x)); Z.y = Math.max(-my, Math.min(my, Z.y));
}
// Acerca dejando quieto el punto (cx, cy) de la pantalla
function zTo(s, cx, cy, anim) {
  const r = zstage.getBoundingClientRect(), ox = r.left + r.width / 2, oy = r.top + r.height / 2;
  const px = (cx ?? ox) - ox, py = (cy ?? oy) - oy, ns = Math.max(1, Math.min(6, s)), k = ns / Z.s;
  Z.x = px - (px - Z.x) * k; Z.y = py - (py - Z.y) * k; Z.s = ns; zClamp(); zApply(anim);
}
function zBase() {
  const p = [...Z.pts.values()];
  Z.base = { s: Z.s, x: Z.x, y: Z.y, p: p.map(q => ({ ...q })), d: p.length > 1 ? Math.hypot(p[0].x - p[1].x, p[0].y - p[1].y) : 0,
    c: p.length > 1 ? { x: (p[0].x + p[1].x) / 2, y: (p[0].y + p[1].y) / 2 } : p[0] };
}
zstage.addEventListener("pointerdown", e => {
  zstage.setPointerCapture(e.pointerId); Z.pts.set(e.pointerId, { x: e.clientX, y: e.clientY }); zBase();
  if (Z.pts.size === 1) {
    const now = Date.now();
    if (now - Z.tap < 320 && Math.hypot(e.clientX - Z.tx, e.clientY - Z.ty) < 30) { zTo(Z.s > 1.2 ? 1 : 3, e.clientX, e.clientY, true); Z.tap = 0; }
    else { Z.tap = now; Z.tx = e.clientX; Z.ty = e.clientY; }
  }
});
zstage.addEventListener("pointermove", e => {
  if (!Z.pts.has(e.pointerId)) return;
  Z.pts.set(e.pointerId, { x: e.clientX, y: e.clientY });
  const p = [...Z.pts.values()], b = Z.base;
  if (p.length === 1 && b.p.length === 1) { Z.x = b.x + p[0].x - b.p[0].x; Z.y = b.y + p[0].y - b.p[0].y; zClamp(); zApply(); }
  else if (p.length >= 2 && b.d) {
    const d = Math.hypot(p[0].x - p[1].x, p[0].y - p[1].y), c = { x: (p[0].x + p[1].x) / 2, y: (p[0].y + p[1].y) / 2 };
    Z.s = b.s; Z.x = b.x + c.x - b.c.x; Z.y = b.y + c.y - b.c.y; zTo(b.s * d / b.d, c.x, c.y);
  }
});
["pointerup", "pointercancel"].forEach(t => zstage.addEventListener(t, e => { Z.pts.delete(e.pointerId); zBase(); }));
zstage.addEventListener("wheel", e => { e.preventDefault(); zTo(Z.s * Math.exp(-e.deltaY / 350), e.clientX, e.clientY); }, { passive: false });
$(".zctl").addEventListener("click", e => { const b = e.target.closest("[data-z]"); if (!b) return; const z = +b.dataset.z; z ? zTo(Z.s * (z > 0 ? 1.6 : 1 / 1.6), null, null, true) : zTo(1, null, null, true); });
function openZoom(id) {
  const p = CATALOGO.find(x => x.id === id); if (!p) return;
  Z.id = id; Z.s = 1; Z.x = 0; Z.y = 0; Z.pts.clear();
  zimg.src = IMGS[p.id] || "data:image/svg+xml;charset=utf-8," + encodeURIComponent(cartSVG(p).replace("<svg", '<svg xmlns="http://www.w3.org/2000/svg"'));
  zimg.alt = p.nombre; zApply();
  const d = delivery(city(), p), alias = p.refs.filter(r => r !== p.ref);
  $("#zinfo").innerHTML = `<span class="m" style="font-weight:800;text-transform:uppercase;letter-spacing:.07em;font-size:11.5px">${esc(p.marca)} · ${UBIC[ubic(p)]}</span>
    <h3 id="z-name">${esc(p.nombre)}</h3>
    <div class="zref">${esc(p.ref)}</div>
    ${alias.length ? `<div class="m" style="font-size:12.5px">También aparece como:</div><div class="alias">${alias.map(r => `<span>${esc(r)}</span>`).join("")}</div>` : ""}
    ${p.desc ? `<p style="margin:0;font-size:14.5px">${esc(p.desc)}</p>` : ""}
    <div class="fits">${p.modelos.length ? "Sirve para " + esc(p.modelos.join(", ")) + " y más." : esc(p.nota || "")}</div>
    <div class="row" style="justify-content:space-between"><div><div class="price">${COP(p.precio)}</div><div class="eta">${ICON.truck}<span>${city() ? esc(d.corto) : "Elige tu ciudad para ver la entrega"}</span></div></div>
    ${cart ? `<button class="btn" type="button" data-zclose>Volver al pedido</button>` : `<button class="btn" type="button" data-zbuy="${p.id}">Pedir</button>`}</div>`;
  $("#zoom").hidden = false; document.body.style.overflow = "hidden"; $("#z-close").focus();
}
function closeZoom() { $("#zoom").hidden = true; Z.id = null; if ($("#sheet").hidden) document.body.style.overflow = ""; }
$("#z-close").addEventListener("click", closeZoom);
document.addEventListener("click", e => {
  const z = e.target.closest("[data-zoom]"); if (z) { e.preventDefault(); openZoom(z.dataset.zoom); return; }
  if (e.target.closest("[data-zclose]")) { closeZoom(); return; }
  const b = e.target.closest("[data-zbuy]"); if (b) { closeZoom(); startOrder(b.dataset.zbuy); }
});
document.addEventListener("keydown", e => {
  if ($("#zoom").hidden) return;
  if (e.key === "Escape") { e.stopImmediatePropagation(); closeZoom(); }
  else if (e.key === "+" || e.key === "=") zTo(Z.s * 1.6, null, null, true);
  else if (e.key === "-") zTo(Z.s / 1.6, null, null, true);
}, true);

/* Compartir con la foto (en celulares que lo permiten) */
function fileFromURL(url, name) {
  const [hd, b64] = url.split(","), bin = atob(b64), u = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i);
  return new File([u], name, { type: hd.slice(5, hd.indexOf(";")) });
}
document.addEventListener("click", e => {
  const a = e.target.closest("[data-share]"); if (!a) return;
  const p = CATALOGO.find(x => x.id === a.dataset.share); if (!p || !IMGS[p.id] || !navigator.canShare) return;
  let data;
  try { data = { title: p.nombre, text: shareTxt(p), files: [fileFromURL(IMGS[p.id], `filtro-${p.ref}.jpg`)] }; if (!navigator.canShare(data)) return; } catch { return; }
  e.preventDefault();
  navigator.share(data).catch(err => { if (err?.name !== "AbortError") window.open(a.href, "_blank", "noopener"); });
});

function startOrder(id) {
  const p = CATALOGO.find(x => x.id === id); if (!p) return;
  const prev = store.get("fy_cliente", {});
  cart = { p, qty: 1, pack: false, pago: "linea", entrega: null, step: 1, id: null,
    cli: { nombre: prev.nombre || "", tel: prev.tel || "", email: prev.email || "", ciudad: city(), dir: prev.dir || "", barrio: prev.barrio || "", indicaciones: "", modelo: modeloBuscado(), recordar: !!prev.recordar } };
  fixEntrega(); renderStep();
}
// Solo se usa lo buscado si era el modelo de un nevecón (no la referencia del filtro)
function modeloBuscado() {
  const q = $("#q").value.trim(), h = buscar(q)[0];
  return h && h.por.startsWith("nevecón") ? q.toUpperCase() : "";
}
// Producto con link de pago propio: se paga en línea cuando es 1 unidad (el link tiene el valor de 1 filtro)
// El link solo se usa si su monto (linkMonto) es igual al precio actual: así nunca se cobra un valor viejo
const conLink = () => typeof FY_WEB === "undefined" && !!cart && !!cart.p.linkPago && cart.p.linkMonto === cart.p.precio && !cart.pack && cart.qty === 1 && !(cart.entrega === "instalacion" && costoInst(cart.p));
function fixEntrega() {
  const d = delivery(cart.cli.ciudad, cart.p);
  const ok = d.local ? (d.instala && cart.p.stock ? ["instalacion", "domicilio"] : ["domicilio"]) : ["transportadora"];
  if (!ok.includes(cart.entrega)) cart.entrega = ok[0];
}
function totals() {
  const d = delivery(cart.cli.ciudad, cart.p), p = cart.p;
  const unidades = cart.pack ? 2 : cart.qty;
  const bruto = p.precio * unidades, desc = cart.pack ? bruto - packPrecio(p) : 0;
  const ent = cart.entrega === "instalacion" ? costoInst(p) : d.envio;
  return { d, unidades, bruto, desc, ent, total: bruto - desc + ent };
}
const progress = n => `<div class="progress" aria-label="Paso ${n} de 3"><div class="${n >= 1 ? "on" : ""}">1. Pedido</div><div class="${n >= 2 ? "on" : ""}">2. Tus datos</div><div class="${n >= 3 ? "on" : ""}">3. Confirmar</div></div>`;
const entregaTxt = e => e === "instalacion" ? "Domicilio + instalación" : e === "domicilio" ? "Domicilio" : "Envío por transportadora";
function sumHTML() {
  const t = totals();
  return `<div class="sum"><span>${t.unidades} × ${esc(cart.p.ref)}</span><span>${COP(t.bruto)}</span>
    ${t.desc ? `<span class="save">Descuento pack anual</span><span class="save">− ${COP(t.desc)}</span>` : ""}
    <span>${entregaTxt(cart.entrega)}</span><span${t.ent ? "" : ' class="save"'}>${gratis(t.ent)}</span>
    <span class="t">Total</span><span class="t">${COP(t.total)}</span></div>`;
}
