        ${d.local ? `<label><input type="radio" name="entrega" value="domicilio" ${cart.entrega === "domicilio" ? "checked" : ""}><span><b>Solo entrega, sin instalación</b><small>${esc(d.largo)} Tú lo instalas: te mandamos el video.</small></span><span class="amt save">${gratis(d.envio)}</span></label>`
                  : `<label><input type="radio" name="entrega" value="transportadora" checked><span><b>Envío por transportadora</b><small>${esc(d.largo)}</small></span><span class="amt save">${gratis(d.envio)}</span></label>`}
