}
function validStep2() {
  const k = cart.cli, wa = celularCO(k.tel);
  const bad = { nombre: k.nombre.length < 3, tel: !wa, ciudad: !k.ciudad, barrio: !k.barrio, dir: k.dir.length < 5, email: !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(k.email || "") };
  Object.entries(bad).forEach(([f, b]) => $("#f-" + f).classList.toggle("bad", b));
  const msgs = { nombre: "tu nombre", tel: "un celular válido (10 dígitos que empiezan por 3)", email: "un correo válido", ciudad: "la ciudad", barrio: "el barrio", dir: "la dirección" };
  const falta = Object.keys(bad).filter(f => bad[f]);
  if (falta.length) { $("#c-err").textContent = "Falta " + falta.map(f => msgs[f]).join(", ") + "."; $("#c-" + falta[0])?.focus(); return false; }
  k.wa = wa; k.tel = wa.slice(2).replace(/(\d{3})(\d{3})(\d{4})/, "$1 $2 $3");
  return true;
}
