/* ===================== VIDA DEL FILTRO ===================== */
// Anillo animado: pct de vida usada (0–1+)
function gaugeHTML(pct, grande, chico, sm) {
  const r = 52, L = 2 * Math.PI * r, v = Math.max(0, Math.min(1, pct));
  const col = pct >= 1 ? "var(--bad)" : pct >= .8 ? "var(--warn)" : "var(--ok)";
  return `<div class="gauge${sm ? " sm" : ""}"><svg viewBox="0 0 120 120" aria-hidden="true"><circle class="trk" cx="60" cy="60" r="${r}"/><circle class="val" cx="60" cy="60" r="${r}" stroke="${col}" stroke-dasharray="${L}" stroke-dashoffset="${L}" data-off="${L * (1 - v)}"/></svg><div class="lbl"><b>${grande}</b><span>${chico}</span></div></div>`;
}
// Arranca la animación del anillo después de pintarlo
function animarGauges(root) { requestAnimationFrame(() => requestAnimationFrame(() => root.querySelectorAll(".val[data-off]").forEach(c => { c.style.strokeDashoffset = c.dataset.off; }))); }
const DIA = 864e5;
function vidaFiltro(desde) {
  const fin = new Date(desde); fin.setMonth(fin.getMonth() + NEGOCIO.mesesCambio);
  const total = fin - desde, usado = Date.now() - desde;
  return { pct: usado / total, dias: Math.ceil((fin - Date.now()) / DIA), fin };
}
function renderSalud() {
  const v = $("#sl-fecha").value, sint = $$("#sl-sint [aria-pressed=true]").map(b => b.dataset.s);
  store.set("fy_salud", { fecha: v, sint });
  if (!v) {
    $("#sl-gauge").innerHTML = gaugeHTML(0, "?", "elige la fecha");
    $("#sl-out").innerHTML = ""; return;
  }
  const [y, m] = v.split("-").map(Number), desde = new Date(y, m - 1, 15);
  if (desde > new Date()) { $("#sl-out").innerHTML = `<div class="sl-verdict warn">Esa fecha está en el futuro. Revisa el mes.</div>`; return; }
  const { pct, dias, fin } = vidaFiltro(desde);
  // Cada síntoma cuenta: con 2 o más, el filtro ya está saturado aunque no se cumpla el tiempo
  const urg = Math.min(1.2, pct + sint.length * .2), queda = Math.max(0, Math.round((1 - pct) * 100));
  $("#sl-gauge").innerHTML = gaugeHTML(urg, pct >= 1 ? "0 %" : queda + " %", pct >= 1 ? "de vida: ya se venció" : "de vida le queda");
  const marca = vista.marca !== "top" ? vista.marca : "";
  const nivel = urg >= 1 ? "bad" : urg >= .8 ? "warn" : "ok";
  const txt = {
    bad: `<b>Toca cambiarlo ya.</b> ${pct >= 1 ? `Se venció hace ${Math.abs(dias)} días.` : "Lo que notas en el agua indica que el filtro se saturó."} Un filtro vencido deja pasar cloro, sedimento y mal sabor, y puede tapar la válvula del dispensador.`,
    warn: `<b>Ya casi.</b> ${dias > 0 ? `Le quedan unos ${dias} días.` : ""} ${sint.length ? "Y lo que notas en el agua dice que ya se está saturando." : "Pídelo de una vez para que te llegue antes de que se venza."}`,
    ok: `<b>Tu filtro está bien.</b> Le quedan unos ${dias} días. Toca cambiarlo hacia el ${fin.toLocaleDateString("es-CO", { day: "numeric", month: "long", year: "numeric" })}.`
  }[nivel];
  $("#sl-out").innerHTML = `<div class="sl-verdict ${nivel} rise">${txt}
    <div class="row">${nivel !== "ok" ? `<button class="btn" type="button" data-sl-ver>Ver filtros${marca ? " " + esc(marca) : ""}</button>` : ""}<button class="btn ghost" type="button" data-sl-ics>Recordármelo en el calendario</button></div>
    <span class="m" id="sl-msg"></span></div>`;
  animarGauges($("#salud"));
}
(() => {
  const s = store.get("fy_salud", {});
  const max = new Date(); $("#sl-fecha").max = max.toISOString().slice(0, 7);
  if (s.fecha) $("#sl-fecha").value = s.fecha;
