// Dentro de Claude no se pueden descargar archivos .ics: se abre el evento en Google Calendar
function abrirCalendario(desde, hasta, titulo, msg) {
  const u = "https://calendar.google.com/calendar/render?action=TEMPLATE&text=" + encodeURIComponent(titulo) + "&dates=" + desde + "/" + hasta
    + "&details=" + encodeURIComponent(`Toca cambiar el filtro (cada ${NEGOCIO.mesesCambio} meses). Pídelo en ${NEGOCIO.nombre}: https://wa.me/${NEGOCIO.whatsapp}`);
  window.open(u, "_blank", "noopener");
  msg.innerHTML = `Se abrió Google Calendar: toca <b>Guardar</b>. Si no se abrió, <a href="${u}" target="_blank" rel="noopener">toca aquí</a>.`;
}
// Evento de calendario (todo el día) con aviso 3 días antes
async function guardarICS(fecha, uid, msg) {
  const ymd = d => d.toISOString().slice(0, 10).replace(/-/g, "");
  const ics = ["BEGIN:VCALENDAR", "VERSION:2.0", "PRODID:-//FiltrosNevecones//ES", "BEGIN:VEVENT", `UID:${uid}@filtrosnevecones`, `DTSTAMP:${new Date().toISOString().replace(/[-:]/g, "").slice(0, 15)}Z`,
    `DTSTART;VALUE=DATE:${ymd(fecha)}`, `DTEND;VALUE=DATE:${ymd(new Date(fecha.getTime() + DIA))}`, "SUMMARY:Cambiar el filtro de agua del nevecón",
    `DESCRIPTION:Pídelo en ${NEGOCIO.nombre}: https://wa.me/${NEGOCIO.whatsapp}`, "BEGIN:VALARM", "TRIGGER:-P3D", "ACTION:DISPLAY", "DESCRIPTION:En 3 días toca cambiar el filtro", "END:VALARM", "END:VEVENT", "END:VCALENDAR"].join("\r\n");
  abrirCalendario(ymd(fecha), ymd(new Date(fecha.getTime() + DIA)), "Cambiar el filtro de agua del nevecón", msg);
}

