// Fotos reales: se reducen a 600 px y se guardan en este teléfono
async function shrink(file) {
  const img = await new Promise((r, j) => { const i = new Image(); i.onload = () => r(i); i.onerror = j; i.src = URL.createObjectURL(file); });
  const k = Math.min(1, 600 / Math.max(img.naturalWidth, img.naturalHeight));
  const c = document.createElement("canvas"); c.width = Math.round(img.naturalWidth * k); c.height = Math.round(img.naturalHeight * k);
  const x = c.getContext("2d"); x.fillStyle = "#fff"; x.fillRect(0, 0, c.width, c.height); x.drawImage(img, 0, 0, c.width, c.height);
  return c.toDataURL("image/jpeg", 0.82);
}
function invMsg(t) { $("#inv-msg").innerHTML = t ? `<div class="note">${esc(t)}</div>` : ""; }
$("#inv").addEventListener("change", async e => {
