    if (!store.set("fy_imgs", IMGS)) invMsg("Este teléfono no tiene espacio para más fotos en el prototipo.");
  } catch { invMsg("No se pudo leer esa foto. Prueba con otra."); }
  renderSeller(); const q = $("#q").value.trim(); q ? doSearch(q, false) : showPopular();
});

