    const msg = `Hola ${nombre}, te escribimos de ${NEGOCIO.nombre}. Ya se cumplen ${NEGOCIO.mesesCambio} meses del filtro de agua de tu nevecón (${x.ref}). ¿Te lo llevamos ${INSTALA_EN.includes(x.ciudad) ? "e instalamos " : ""}esta semana? Responde SÍ y lo agendamos. Si no quieres más recordatorios, responde NO.`;
    return `<div class="li"><div style="min-width:0"><b>${esc(x.cliente.nombre)}</b>${x.demo ? ' <span class="example">Ejemplo</span>' : ""}<div class="m">${esc(x.ref)} · ${esc(x.ciudad)} · cambio ${new Date(x.cambio).toLocaleDateString("es-CO", { day: "numeric", month: "short", year: "numeric" })}</div><div style="margin-top:4px">${est}</div></div>
      <div style="display:flex;align-items:center"><a class="btn wa" style="padding:8px 12px;font-size:14px" href="${waTo(x.cliente.wa, msg)}" target="_blank" rel="noopener" data-rec="${esc(x.id)}">Recordar</a></div></div>`;
  }).join("")}</div>`;
}
