const BRAND = { deep: "#0b1f6b", deep2: "#1236a8", glow: "#38d6ff", ink: "#0b1a45", white: "#ffffff", muted: "#566287" };
const prodOpts = (todos) => (todos ? `<option value="">Cualquier filtro (genérico)</option>` : "") + CATALOGO.map(p => `<option value="${p.id}">${esc(p.ref)} · ${esc(p.nombre)}</option>`).join("");
