function qrModules(text) {
  if (typeof qrcode !== "function") return null;
  try { const q = qrcode(0, "M"); q.addData(text); q.make(); return q; } catch { return null; }
}
function drawQR(ctx, text, x, y, size) {
  const q = qrModules(text);
  if (!q) { ctx.fillStyle = "#eee"; ctx.fillRect(x, y, size, size); ctx.fillStyle = "#888"; ctx.font = "14px sans-serif"; ctx.fillText("QR sin conexión", x + 8, y + size / 2); return false; }
  const n = q.getModuleCount(), quiet = 2, cell = size / (n + quiet * 2);
  ctx.fillStyle = "#fff"; ctx.fillRect(x, y, size, size);
  ctx.fillStyle = "#000";
  for (let r = 0; r < n; r++) for (let c = 0; c < n; c++) if (q.isDark(r, c)) ctx.fillRect(Math.floor(x + (c + quiet) * cell), Math.floor(y + (r + quiet) * cell), Math.ceil(cell), Math.ceil(cell));
  return true;
}
function rr(ctx, x, y, w, h, r) { ctx.beginPath(); ctx.moveTo(x + r, y); ctx.arcTo(x + w, y, x + w, y + h, r); ctx.arcTo(x + w, y + h, x, y + h, r); ctx.arcTo(x, y + h, x, y, r); ctx.arcTo(x, y, x + w, y, r); ctx.closePath(); }
function drop(ctx, x, y, s) { ctx.save(); ctx.translate(x, y); ctx.scale(s / 24, s / 24); ctx.fillStyle = BRAND.glow; ctx.fill(new Path2D("M12 2.5C9 6.5 6 9.6 6 13.5a6 6 0 0 0 12 0c0-3.9-3-7-6-11z")); ctx.restore(); }
function wrapText(ctx, text, x, y, maxW, lh) {
  const words = String(text).split(" "); let line = "", yy = y;
  for (const w of words) { const t = line ? line + " " + w : w; if (ctx.measureText(t).width > maxW && line) { ctx.fillText(line, x, yy); line = w; yy += lh; } else line = t; }
  if (line) ctx.fillText(line, x, yy); return yy;
}
async function productImage(p) {   // foto real, o el dibujo del filtro
  const src = IMGS[p.id] || "data:image/svg+xml;charset=utf-8," + encodeURIComponent(cartSVG(p).replace("<svg ", '<svg xmlns="http://www.w3.org/2000/svg" width="270" height="400" '));
  return new Promise(r => { const i = new Image(); i.onload = () => r(i); i.onerror = () => r(null); i.src = src; });
}
const fontsReady = () => (document.fonts && document.fonts.ready ? document.fonts.ready.catch(() => {}) : Promise.resolve());
async function saveCanvas(canvas, filename, msgEl) {
  const blob = await new Promise(r => canvas.toBlob(r, "image/png"));
  try {
    if (downloads) { await downloads.save({ filename, data: blob }); msgEl.textContent = "Imagen descargada."; return; }
    const a = document.createElement("a"); a.href = URL.createObjectURL(blob); a.download = filename; document.body.append(a); a.click(); setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 2000);
    msgEl.textContent = "Si no se descargó, mantén presionada la imagen y toca Guardar.";
  } catch { msgEl.textContent = "No se descargó. Mantén presionada la imagen y toca Guardar."; }
}

/* --- Sticker QR: hoja A4 de 8 --- */
async function makeStickers() {
  await fontsReady();
  const p = CATALOGO.find(x => x.id === $("#st-prod").value) || null;
  const f = $("#st-fecha").value ? new Date($("#st-fecha").value + "T12:00:00") : null;
  const fecha = f ? f.toLocaleDateString("es-CO", { day: "numeric", month: "long", year: "numeric" }) : "";
  const ref = p ? p.ref : "";
  const qrText = waLink(`Hola ${NEGOCIO.nombre}, quiero cambiar el filtro de mi nevecón${ref ? ` (${ref})` : ""}. Lo vi en el sticker.`);
  const W = 1240, H = 1754, cols = 2, rows = 4, m = 40, g = 24;
  const sw = (W - m * 2 - g) / cols, sh = (H - m * 2 - g * (rows - 1)) / rows;
  const c = document.createElement("canvas"); c.width = W; c.height = H;
  const x = c.getContext("2d"); x.fillStyle = "#fff"; x.fillRect(0, 0, W, H);
  for (let r = 0; r < rows; r++) for (let k = 0; k < cols; k++) {
    const sx = m + k * (sw + g), sy = m + r * (sh + g);
    x.save(); rr(x, sx, sy, sw, sh, 26); x.fillStyle = BRAND.deep; x.fill(); x.restore();
    x.strokeStyle = "#cfd8d7"; x.setLineDash([10, 8]); rr(x, sx - 8, sy - 8, sw + 16, sh + 16, 32); x.stroke(); x.setLineDash([]);
    const qs = Math.round(Math.min(sh - 60, sw * 0.42)), tw = sw - qs - 74;   // QR a la derecha, texto a la izquierda
    drawQR(x, qrText, sx + sw - qs - 26, sy + (sh - qs) / 2, qs);
    drop(x, sx + 24, sy + 26, 28);
    x.fillStyle = "#fff"; x.font = "800 27px 'Bricolage Grotesque', sans-serif"; x.fillText(NEGOCIO.nombre, sx + 58, sy + 50, tw - 34);
    x.fillStyle = BRAND.glow; x.font = "700 16px Manrope, sans-serif"; x.fillText("PRÓXIMO CAMBIO DEL FILTRO", sx + 26, sy + 100, tw);
    x.fillStyle = "#fff"; x.font = "800 34px 'Bricolage Grotesque', sans-serif"; const yd = wrapText(x, fecha || "__ / __ / ____", sx + 26, sy + 142, tw, 38);
    if (ref) { x.fillStyle = "#c4e4de"; x.font = "500 19px 'JetBrains Mono', monospace"; x.fillText("Filtro " + ref, sx + 26, yd + 40, tw); }
    x.fillStyle = "#fff"; x.font = "700 19px Manrope, sans-serif"; wrapText(x, "Escanéame con la cámara y pídelo por WhatsApp", sx + 26, sy + sh - 82, tw, 24);
  }
  x.fillStyle = BRAND.muted; x.font = "16px Manrope, sans-serif"; x.fillText("Imprime en papel adhesivo y recorta por la línea punteada.", m, H - 12);
  const url = c.toDataURL("image/png");
  $("#st-out").innerHTML = `<img class="prev rise" src="${url}" alt="Hoja de stickers con código QR"><div class="row"><button class="btn" type="button" id="st-dl">Descargar hoja (PNG)</button><span class="sub" id="st-msg"></span></div><p class="sub" style="margin:0">Imprímela en papel adhesivo en cualquier papelería. ${typeof qrcode === "function" ? "Prueba un QR con la cámara antes de imprimir." : "Sin conexión no se pudo crear el QR: vuelve a intentarlo con internet."}</p>`;
  $("#st-dl").onclick = () => saveCanvas(c, `stickers-${ref || "filtro"}.png`, $("#st-msg"));
}
$("#st-go").addEventListener("click", makeStickers);

/* --- Imagen de oferta 1080×1350 --- */
async function makeOffer() {
  await fontsReady();
  const p = CATALOGO.find(x => x.id === $("#of-prod").value); if (!p) return;
  const frase = $("#of-frase").value.trim();
  const W = 1080, H = 1350, c = document.createElement("canvas"); c.width = W; c.height = H;
  const x = c.getContext("2d");
  const gr = x.createRadialGradient(W, 0, 50, W, 0, 1300); gr.addColorStop(0, BRAND.deep2); gr.addColorStop(1, BRAND.deep);
  x.fillStyle = gr; x.fillRect(0, 0, W, H);
  x.strokeStyle = "rgba(56,214,255,.15)"; x.lineWidth = 60; x.beginPath(); x.arc(W - 40, 80, 230, 0, Math.PI * 2); x.stroke();
  drop(x, 70, 62, 52); x.fillStyle = "#fff"; x.font = "800 50px 'Bricolage Grotesque', sans-serif"; x.fillText(NEGOCIO.nombre, 136, 108);
  x.fillStyle = BRAND.glow; x.font = "700 30px Manrope, sans-serif"; x.fillText(("Filtro de agua para nevecón " + p.marca).toUpperCase(), 70, 210);
  x.fillStyle = "#fff"; x.font = "800 74px 'Bricolage Grotesque', sans-serif"; const yEnd = wrapText(x, p.nombre, 70, 300, 600, 80);
  x.fillStyle = "#c4e4de"; x.font = "500 38px 'JetBrains Mono', monospace"; x.fillText(p.ref, 70, yEnd + 70);
  // tarjeta del producto
  x.save(); rr(x, 700, 250, 310, 440, 36); x.fillStyle = "#ffffff"; x.fill(); x.restore();
  const img = await productImage(p);
  if (img) { const r = Math.min(260 / img.width, 390 / img.height); const w = img.width * r, h = img.height * r; x.drawImage(img, 855 - w / 2, 470 - h / 2, w, h); }
  // precio
  x.fillStyle = BRAND.glow; x.font = "800 128px 'Bricolage Grotesque', sans-serif"; x.fillText(COP(p.precio), 70, 830);
  x.fillStyle = "#fff"; x.font = "600 34px Manrope, sans-serif";
  const puntos = ["Envío gratis a toda Colombia", "Pago seguro en línea", "Asesoría por WhatsApp"];
  puntos.forEach((t, i) => { x.fillStyle = BRAND.glow; x.beginPath(); x.arc(86, 905 + i * 58, 9, 0, Math.PI * 2); x.fill(); x.fillStyle = "#fff"; x.fillText(t, 110, 917 + i * 58); });
  if (frase) { x.save(); rr(x, 70, 1100, 640, 86, 43); x.fillStyle = BRAND.glow; x.fill(); x.restore(); x.fillStyle = BRAND.ink; x.font = "800 34px Manrope, sans-serif"; x.fillText(frase.slice(0, 34), 100, 1155); }
  drawQR(x, waLink(`Hola ${NEGOCIO.nombre}, quiero el filtro ${p.ref} que vi en la publicación.`), W - 330, H - 400, 270);
  x.fillStyle = "#fff"; x.font = "700 28px Manrope, sans-serif"; x.fillText("Escanea y pídelo", W - 318, H - 96);
  x.fillStyle = "#c4e4de"; x.font = "500 26px Manrope, sans-serif"; x.fillText("WhatsApp " + NEGOCIO.whatsapp.replace(/^57/, "").replace(/(\d{3})(\d{3})(\d{4})/, "$1 $2 $3"), 70, H - 70);
  const url = c.toDataURL("image/png");
  $("#of-out").innerHTML = `<img class="prev rise" src="${url}" alt="Imagen de oferta"><div class="row"><button class="btn" type="button" id="of-dl">Descargar imagen</button><span class="sub" id="of-msg"></span></div>`;
  $("#of-dl").onclick = () => saveCanvas(c, `oferta-${p.ref}.png`, $("#of-msg"));
}
$("#of-go").addEventListener("click", makeOffer);

