};
function plantilla(p, canal, zona) {   // texto de respaldo sin IA
  const lugar = zona || "toda Colombia";
  const sirve = p.modelos.length ? `Sirve para ${p.modelos.slice(0, 3).join(", ")} y más.` : (p.nota || "");
  const base = `Filtro de agua para nevecón ${p.marca} ${p.ref}. ${sirve} ${COP(p.precio)}. Envío GRATIS a toda Colombia (${NEGOCIO.diasNacional} días hábiles). Te asesoramos por WhatsApp. Pago seguro en línea: tarjeta, PSE, Nequi o botón Bancolombia. Escríbenos por WhatsApp.`;
  return { titulo: `Filtro nevecón ${p.marca} ${p.ref} · ${lugar}`, texto: base, palabras_clave: [p.ref, ...p.refs.slice(1, 3), `filtro nevecón ${p.marca.toLowerCase()}`, "filtro agua nevera Colombia"], mejor_momento: "Entre 6 y 9 p. m., cuando la gente revisa el celular en casa.", consejo: "Pon una foto real del filtro y responde rápido los mensajes." };
}
