    btn.disabled = true; out.innerHTML = `<p class="sub"><span class="spin" aria-hidden="true"></span> Escribiendo la publicación…</p>`;
    const prompt = `Escribe una publicación de venta en español de Colombia (cercano, claro, sin exagerar ni inventar) para una tienda en línea de filtros de agua para neveras y nevecones con envíos a toda Colombia.
Negocio: ${NEGOCIO.nombre}${zona ? " (zona: " + zona + ")" : ""}. envío GRATIS a toda Colombia en ${NEGOCIO.diasNacional} días hábiles por transportadora; pago solo en línea, en página segura (tarjeta, PSE, Nequi o botón Bancolombia).
Producto: ${p.nombre}. Referencia: ${p.ref}. Referencias equivalentes: ${p.refs.join(", ")}. Nevecones que lo usan: ${p.modelos.join(", ")}. Precio: ${COP(p.precio)}. Usa siempre «sirve para» y «referencia equivalente».
Canal: ${CANAL[canal]}.
Reglas: no prometas entrega el mismo día; no digas "el mejor" ni datos que no te di; menciona que el filtro se cambia cada ${NEGOCIO.mesesCambio} meses.
Responde SOLO con JSON: {"titulo":"","texto":"","palabras_clave":[""],"mejor_momento":"cuándo publicarlo","consejo":"un consejo corto para vender más en ese canal"}`;
    try { d = await sample.json(prompt, { modelTier: "default", cache: false }); }
    catch (e) { d = null; out.innerHTML = `<p class="sub">No se pudo usar la IA (${esc(e?.code || "error")}). Te dejo un texto base.</p>`; }
    btn.disabled = false;
  }
  if (!d || !d.texto) d = plantilla(p, canal, zona);
  const full = [d.titulo, d.texto, canal === "instagram" && d.palabras_clave ? d.palabras_clave.map(k => "#" + String(k).replace(/[^\p{L}\p{N}]/gu, "")).join(" ") : ""].filter(Boolean).join("\n\n");
  out.innerHTML = `<div class="copybox rise" id="pub-text">${esc(full)}</div>
