    ${d.consejo ? `<div class="note info">${esc(d.consejo)}</div>` : ""}
    <div class="row"><button class="btn" type="button" id="pub-copy">Copiar texto</button><a class="btn ghost" href="https://wa.me/?text=${encodeURIComponent(full)}" target="_blank" rel="noopener">${ICON.wa}Enviar a WhatsApp</a></div>
    ${sample ? "" : `<p class="sub" style="margin:0">Texto base. Dentro de Claude la IA lo escribe a la medida de cada red.</p>`}`;
  $("#pub-copy").onclick = async () => {
    try { await navigator.clipboard.writeText(full); $("#pub-copy").textContent = "Copiado"; }
    catch { const r = document.createRange(); r.selectNodeContents($("#pub-text")); const s = getSelection(); s.removeAllRanges(); s.addRange(r); $("#pub-copy").textContent = "Texto seleccionado: cópialo"; }
  };
});

/* ===================== ASISTENTE CON IA ===================== */
let chatTurns = [], chatCtl = null;
const SUGS = ["¿Qué filtro usa mi nevecón?", "¿Cada cuánto se cambia?", "¿Cuánto cuesta el envío?", "¿Lo instalan?", "¿Cómo pago?"];
function reglasAsistente() {
  const cat = CATALOGO.filter(p => ["Samsung", "LG", "Whirlpool", "GE"].includes(p.marca)).map(p =>
    `- id ${p.id} | ${p.nombre} | ref ${p.ref} | también: ${p.refs.join(", ")} | nevecones: ${p.modelos.join(", ") || "(confirmar con foto)"} | ${COP(p.precio)} | pack de 2: ${COP(packPrecio(p))} | ${p.stock ? "disponible" : "por encargo"}${p.linkPago ? " | pago en línea" : ""}${p.nota ? " | " + p.nota : ""}`).join("\n");
  return `Eres el asistente de ventas de ${NEGOCIO.nombre}, una tienda de filtros de agua para neveras y nevecones (Samsung, LG, Whirlpool EveryDrop y GE General Electric), con envíos a toda Colombia. No digas en qué ciudad está la tienda. Hablas con un cliente desde la app de la tienda.
DATOS DEL NEGOCIO (no inventes otros):
- Envío GRATIS a toda Colombia por transportadora: llega en ${NEGOCIO.diasNacional} días hábiles.
- Instalación: el cliente lo instala en minutos con el paso a paso de la página; para cualquier duda, asesoría por WhatsApp. No ofrezcas instalación a domicilio.
- No prometas entrega el mismo día.
- Pagos: solo en línea, en página de pago segura (tarjeta débito o crédito, PSE, Nequi o botón Bancolombia). No hay pago contra entrega ni transferencias.
- Asesoría por WhatsApp al ${NEGOCIO.whatsapp.replace(/^57/, "")}. El filtro se cambia cada ${NEGOCIO.mesesCambio} meses o cuando el agua cambie de sabor u olor.
- Pack anual de 2 filtros con descuento.
CATÁLOGO:
${cat}
REGLAS:
1. Responde en español de Colombia, amable y corto (máximo 5 líneas). Tutea.
2. Recomienda SOLO productos del catálogo. Nunca inventes equivalencias: si el cliente da un modelo de nevecón que no está en la lista, o no estás seguro, pídele la foto del filtro viejo o de la etiqueta de adentro del nevecón (puede usar el botón "Tomar foto del filtro" de la app) o que escriba la referencia impresa en el filtro.
3. Si piden un filtro que no está en el catálogo, di que lo podemos conseguir y que escriban por WhatsApp.
5. Usa siempre «sirve para» y «referencia equivalente». Si el cliente pregunta si es de fábrica, dile que se lo confirmamos por WhatsApp.
4. Si recomiendas productos, termina con una última línea exactamente así: PRODUCTOS: id1, id2 (máximo 3 ids del catálogo). Si no recomiendas productos, no pongas esa línea.`;
}
function renderChat(streaming) {
  const box = $("#chat"); if (!box) return;
  box.innerHTML = (chatTurns.length ? "" : `<div class="bub ai">¡Hola! Soy el asistente de ${esc(NEGOCIO.nombre)}. Pregúntame qué filtro usa tu nevecón, precios, envíos o cómo instalarlo.</div>`) +
    chatTurns.map(t => {
      if (t.role === "user") return `<div class="bub me">${esc(t.content)}</div>`;
      const { texto, ids } = splitProductos(t.content);
      const prods = ids.map(id => CATALOGO.find(p => p.id === id)).filter(Boolean);
      return `<div class="bub ai">${esc(texto)}</div>` + prods.map(p => `<div class="mini">${IMGS[p.id] ? `<img src="${IMGS[p.id]}" alt="">` : cartSVG(p)}<div style="min-width:0"><b style="font-size:14px">${esc(p.nombre)}</b><div class="m">${COP(p.precio)} · envío gratis</div></div><button class="btn" type="button" data-buy="${p.id}">Pedir</button></div>`).join("");
    }).join("") + (streaming ? `<div class="bub ai" id="bub-live"><span class="spin" aria-hidden="true"></span> Escribiendo…</div>` : "");
  const sh = $("#sheet"); sh.scrollTop = sh.scrollHeight;
}
function splitProductos(text) {
  const m = /\n?\s*PRODUCTOS:\s*([^\n]*)\s*$/i.exec(text || "");
  return m ? { texto: text.slice(0, m.index).trim(), ids: m[1].split(/[,\s]+/).map(s => s.trim()).filter(Boolean).slice(0, 3) } : { texto: (text || "").trim(), ids: [] };
}
function openChat() {
  cart = null;
  openSheet(`<div class="grab" aria-hidden="true"></div>
    <div class="row" style="justify-content:space-between"><h3 id="sh-title">Pregúntale a ${esc(NEGOCIO.nombre)}</h3><button class="btn ghost" type="button" data-close style="padding:8px 12px">Cerrar</button></div>
    <div class="chat" id="chat" aria-live="polite"></div>
    <div class="sugs" id="sugs">${SUGS.map(s => `<button type="button" data-sug="${esc(s)}">${esc(s)}</button>`).join("")}</div>
    <form class="chatform" id="chatform"><input id="chatin" placeholder="Escribe tu pregunta…" autocomplete="off" aria-label="Tu pregunta"><button class="btn" type="submit">Enviar</button></form>`);
  renderChat(false);
}
async function askChat(q) {
  if (!sample || !q.trim()) return;
  chatTurns.push({ role: "user", content: q.trim() });
  $("#sugs") && ($("#sugs").hidden = true);
  renderChat(true);
  chatCtl?.abort(); chatCtl = new AbortController();
  try {
    const turns = [{ role: "user", content: reglasAsistente() }, ...chatTurns.slice(-10)];
    const { text } = await sample(turns, { modelTier: "quick", cache: false, signal: chatCtl.signal,
      onText: ({ text }) => { const live = $("#bub-live"); if (live) live.textContent = splitProductos(text).texto || "…"; } });
    chatTurns.push({ role: "assistant", content: text });
  } catch (e) {
    if (e?.code !== "cancelled") chatTurns.push({ role: "assistant", content: e?.code === "not_granted" ? "No tengo permiso para responder aquí. Escríbenos por WhatsApp y te ayudamos." : "No pude responder ahora. Intenta de nuevo o escríbenos por WhatsApp." });
  }
  renderChat(false);
}
$("#fab").addEventListener("click", openChat);
$("#sheet").addEventListener("submit", e => {
  if (e.target.id !== "chatform") return;
  e.preventDefault(); const i = $("#chatin"); const q = i.value; i.value = ""; askChat(q);
});
$("#sheet").addEventListener("click", e => {
  const s = e.target.closest("[data-sug]"); if (s) { askChat(s.dataset.sug); return; }
  const b = e.target.closest("[data-buy]"); if (b && !cart) { chatCtl?.abort(); startOrder(b.dataset.buy); }
});
(async () => { for (let i = 0; i < 40 && !sample; i++) await new Promise(r => setTimeout(r, 250)); $("#fab").hidden = !sample || !$("#v-buscar").style.display.includes("flex") || $("#v-buscar").hidden; })();

/* Botón flotante de WhatsApp: abre el chat con un asesor y avisa a Google Tag Manager ("whatsapp") */
window.dataLayer = window.dataLayer || [];
$("#wa-flot").href = waTo(NEGOCIO.whatsapp, `Hola, ${NEGOCIO.nombre}. Quiero asesoría con un filtro de agua para mi nevecón.`);
document.querySelectorAll("[data-wa-asesor]").forEach(x => { x.href = $("#wa-flot").href; x.target = "_blank"; x.rel = "noopener"; });
document.addEventListener("click", e => {
  if (window.FYPago) return; // en la tienda web estos eventos los manda carrito.js
  const a = e.target.closest('a[href*="wa.me/"]'); if (a) dataLayer.push({ event: "whatsapp", ubicacion: a.id === "wa-flot" ? "boton_flotante" : "enlace" });
  const w = e.target.closest('a[href*="checkout.wompi.co"]'); if (w && cart) dataLayer.push({ event: "pago_wompi", value: totals().total, currency: "COP" });
}, true);

renderTrust(); showPopular(); renderOrders(); renderSeller();

/* ===================== TIENDA WEB: CARRITO ===================== */
document.addEventListener("click", e => {
  const a = e.target.closest("[data-cart-add], [data-cart-now]"); if (!a || !cart || !window.FYCart) return;
  FYCart.agregar(cart.p.id, cart.pack, cart.pack ? 1 : cart.qty);
  if (a.hasAttribute("data-cart-now")) { location.href = "/carrito.php"; return; }
  closeSheet(); FYCart.aviso((cart.pack ? "Pack anual de " : "") + corto(cart.p) + " agregado al carrito");
});
/* ===================== TIENDA WEB: PAGO CON WOMPI ===================== */
document.addEventListener("click", async e => {
  const b = e.target.closest("#c-pagar"); if (!b || !cart) return;
  const t = totals(), k = cart.cli, old = b.innerHTML;
  b.disabled = true; b.textContent = "Abriendo el pago seguro…"; $("#c-perr").textContent = "";
  try {
    const r = await fetch(FY_WEB.api + "pedido.php", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({
      pid: cart.p.id, cantidad: t.unidades, pack: cart.pack, entrega: cart.entrega, total: t.total,
      cliente: { nombre: k.nombre, email: k.email, tel: k.wa, ciudad: k.ciudad, barrio: k.barrio, dir: k.dir, indicaciones: k.indicaciones, modelo: k.modelo, recordar: !!k.recordar } }) });
    const j = await r.json().catch(() => ({}));
    if (!r.ok || !j.url) throw new Error(j.mensaje || "No se pudo crear el pedido. Intenta de nuevo.");
    store.set("fy_cliente", { nombre: k.nombre, tel: k.tel, email: k.email, dir: k.dir, barrio: k.barrio, recordar: k.recordar });
    const cambio = new Date(); cambio.setMonth(cambio.getMonth() + NEGOCIO.mesesCambio);
    const orders = store.get("fy_orders", []).filter(o => o.id !== j.ref);
    orders.unshift({ id: j.ref, fecha: new Date().toISOString(), cambio: cambio.toISOString(), producto: cart.p.nombre, ref: cart.p.ref, pid: cart.p.id, qty: t.unidades, pack: cart.pack, ciudad: k.ciudad, entrega: cart.entrega, pago: "linea", total: j.total, eta: delivery(k.ciudad, cart.p).corto, estado: "Pago pendiente", cliente: { recordar: !!k.recordar } });
    store.set("fy_orders", orders.slice(0, 50));
    window.FYPago ? FYPago(j.url, j.total, j.ref) : (location.href = j.url);
  } catch (err) { $("#c-perr").textContent = err.message; b.disabled = false; b.innerHTML = old; }
});
(() => {
  const u = new URLSearchParams(location.search), pid = u.get("p"), marca = u.get("marca");
  if (marca && MARCAS.some(m => m[0] === marca)) { vista = { marca, ubic: "todos" }; renderCatalogo(); }
  if (pid && CATALOGO.some(x => x.id === pid)) setTimeout(() => startOrder(pid), 250);
})();

})();
